pub unsafe fn quadtree_bounds_extend(bounds: *mut quadtree_bounds, x: f64, y: f64) {
    use libc::{fabs, fmax, fmin};
    if bounds.is_null() {
        return;
    }
    let b = &mut *bounds;
    if !b.nw.is_null() {
        let nw = &mut *b.nw;
        nw.x = fmin(x, nw.x);
        nw.y = fmax(y, nw.y);
    }
    if !b.se.is_null() {
        let se = &mut *b.se;
        se.x = fmax(x, se.x);
        se.y = fmin(y, se.y);
    }
    let nw = &*b.nw;
    let se = &*b.se;
    b.width = fabs(nw.x - se.x);
    b.height = fabs(nw.y - se.y);
}
